section.script:
(function () {
  function initOne(wrapper) {
    if (!wrapper || wrapper.dataset.hsInit === '1') return;
    wrapper.dataset.hsInit = '1';
    if (wrapper.hasAttribute('data-peek-init')) wrapper.removeAttribute('data-peek-init');

    const carousel = wrapper.querySelector('#home-systems-carousel-inner') || wrapper.querySelector('.carousel');
    const inner    = carousel && carousel.querySelector('.carousel-inner');
    if (!inner) return;

    const slides     = Array.from(inner.querySelectorAll('.carousel-item'));
    const indicators = Array.from(wrapper.querySelectorAll('.carousel-indicators [data-bs-slide-to]'));
    const btnPrev    = wrapper.querySelector('.carousel-control-prev');
    const btnNext    = wrapper.querySelector('.carousel-control-next');

    if (slides.length < 2) return;

    /* 1) Stop Bootstrap from touching this instance */
    try {
      if (window.bootstrap && bootstrap.Carousel) {
        const inst = bootstrap.Carousel.getOrCreateInstance(carousel, { interval: false, ride: false, touch: false, keyboard: false, wrap: true });
        inst.pause();
      } else if (window.jQuery && $(carousel).carousel) {
        $(carousel).carousel({ interval: false, ride: false, touch: false, keyboard: false, wrap: true });
        $(carousel).carousel('pause');
      }
    } catch (e) {}

    /* 2) Neutralize data-* triggers inside this wrapper (avoid cross-targeting other copies) */
    const killAttrs = wrapper.querySelectorAll('[data-bs-target], [data-bs-slide], [data-bs-slide-to]');
    killAttrs.forEach(function (el) {
      if (el.hasAttribute('data-bs-target')) el.removeAttribute('data-bs-target');
      if (el.hasAttribute('data-bs-slide')) el.removeAttribute('data-bs-slide');
      // keep data-bs-slide-to only if you want Bootstrap dots; we handle dots ourselves, so remove:
      if (el.hasAttribute('data-bs-slide-to')) el.removeAttribute('data-bs-slide-to');
    });

    /* Clean any legacy peek classes */
    slides.forEach(function (el) { el.classList.remove('peek-left','peek-right'); });

    const mod = (n, m) => ((n % m) + m) % m;
    let current = slides.findIndex(function (s) { return s.classList.contains('active'); });
    if (current < 0) current = 0;

    function syncHeight() {
      const card = slides[current] && slides[current].querySelector('.s_card');
      if (card) inner.style.height = card.offsetHeight + 'px';
    }

    function applyPositions() {
      const n = slides.length;

      slides.forEach(function (el, i) {
        el.classList.remove('pos--1','pos-0','pos-1','off--1','off-1','active');
        const d = mod(i - current, n);
        let rel;

        if (n === 2) rel = (d === 0 ? 0 : 1);
        else if (n === 3) rel = (d === 0 ? 0 : (d === 1 ? 1 : -1));
        else { /* n >= 4 */
          if (d === 0) rel = 0;
          else if (d === 1) rel = 1;
          else if (d === n - 1) rel = -1;
          else rel = (d <= Math.floor(n / 2)) ? 2 : -2; /* far side */
        }

        if (rel === 0) el.classList.add('pos-0','active');
        else if (rel === -1) el.classList.add('pos--1');
        else if (rel === 1) el.classList.add('pos-1');
        else if (rel < -1) el.classList.add('off--1');
        else el.classList.add('off-1');
      });

      // Rebuild indicators we just neutralized
      const dots = wrapper.querySelector('.carousel-indicators');
      if (dots) {
        dots.innerHTML = '';
        for (let i = 0; i < slides.length; i++) {
          const b = document.createElement('button');
          b.type = 'button';
          b.className = (i === current ? 'active' : '');
          if (i === current) b.setAttribute('aria-current','true');
          b.setAttribute('aria-label','Carousel indicator');
          b.addEventListener('click', function (e) { e.preventDefault(); goTo(i); });
          dots.appendChild(b);
        }
      }

      requestAnimationFrame(syncHeight);
    }

    function goTo(idx) { current = mod(idx, slides.length); applyPositions(); }
    function next()   { goTo(current + 1); }
    function prev()   { goTo(current - 1); }

    applyPositions();

    /* Our own controls */
    btnNext && btnNext.addEventListener('click', function (e) { e.preventDefault(); next(); });
    btnPrev && btnPrev.addEventListener('click', function (e) { e.preventDefault(); prev(); });

    /* Click peeks */
    inner.addEventListener('click', function (e) {
      const item = e.target.closest('.carousel-item');
      if (!item) return;
      if (item.classList.contains('pos-1')) next();
      else if (item.classList.contains('pos--1')) prev();
    });

    /* Auto-advance */
    let timer = setInterval(next, 5000);
    wrapper.addEventListener('mouseenter', function () { clearInterval(timer); });
    wrapper.addEventListener('mouseleave', function () { timer = setInterval(next, 5000); });

    /* Resize */
    window.addEventListener('resize', function () { syncHeight(); });
  }

  function initAll() {
    // Support many copies, even with duplicate IDs (Odoo editor behavior)
    document.querySelectorAll('#home-systems-carousel').forEach(initOne);
  }

  // Initial run
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initAll);
  } else {
    initAll();
  }

  // Wire a single global observer (avoid multiple observers if script included twice)
  if (!window.__hsCarouselMO) {
    window.__hsCarouselMO = new MutationObserver(function (muts) {
      let found = false;
      for (const m of muts) {
        for (const n of m.addedNodes) {
          if (n && n.nodeType === 1 /* ELEMENT_NODE */) {
            if (n.id === 'home-systems-carousel' || (n.querySelector && n.querySelector('#home-systems-carousel'))) {
              found = true; break;
            }
          }
        }
        if (found) break;
      }
      if (found) initAll();
    });
    window.__hsCarouselMO.observe(document.documentElement, { childList: true, subtree: true });
  }
})();

(function () {
  var root = document.getElementById('home-systems-carousel');
  if (!root) return;

  var inner = root.querySelector('.carousel-inner');
  var items = inner ? inner.querySelectorAll('.carousel-item') : [];
  if (!items || !items.length) return;

  function toggleLastActiveFlag() {
    var last = items[items.length - 1];
    var isLastActive = last.classList.contains('active');
    root.classList.toggle('is-last-active', isLastActive);
  }

  // No load, garantir estado correto
  toggleLastActiveFlag();

  // Atualizar após cada transição do Bootstrap
  root.addEventListener('slid.bs.carousel', toggleLastActiveFlag);
})();

(function () {
  const wrapper = document.getElementById('home-systems-carousel');
  if (!wrapper || wrapper.dataset.peekInit) return;
  wrapper.dataset.peekInit = '1';
  const carousel = wrapper;
  const bsCarousel = window.bootstrap && bootstrap.Carousel
    ? bootstrap.Carousel.getOrCreateInstance(carousel, { interval: false, wrap: true })
    : (window.jQuery ? $(carousel).carousel({ interval: false, wrap: true }).data('bs.carousel') : null);
  if (!bsCarousel) return;
  console.log('Carousel initialized', bsCarousel);
  if (bsCarousel._config) {
    Object.assign(bsCarousel._config, {
      centeredSlides: true,
      watchSlidesProgress: true,
      slidesPerView: 1,
      breakpoints: {
        768: { slidesPerView: 1.5 },
        1024: { slidesPerView: 2 }
      }
    });
  }

  const items = () => carousel.querySelectorAll('.carousel-item');

  function updatePeeks(activeIndex) {
    const all = items();
    all.forEach(i => i.classList.remove('peek-left', 'peek-right'));

    const index = activeIndex !== undefined
      ? activeIndex
      : Array.from(all).findIndex(i => i.classList.contains('active'));

    const next = all[(index + 1) % all.length];
    const prev = all[(index - 1 + all.length) % all.length];
    if (next) next.classList.add('peek-right');
    if (prev) prev.classList.add('peek-left');
  }

  updatePeeks();
  setInterval(() => bsCarousel.next(), 5000);

  carousel.addEventListener('slide.bs.carousel', ev => {
    console.log('slide', ev.from, '->', ev.to, ev.direction);
    wrapper.classList.add('is-sliding');
    const all = items();
    const from = all[ev.from];
    const prev = all[(ev.from - 1 + all.length) % all.length];
    const next = all[(ev.from + 1) % all.length];

    if (ev.direction === 'left') {
      if (prev) prev.classList.remove('peek-left');
      from.classList.add('peek-left');
    } else {
      if (next) next.classList.remove('peek-right');
      from.classList.add('peek-right');
    }
  });
  carousel.addEventListener('slid.bs.carousel', ev => {
    console.log('slid to', ev.to);
    updatePeeks(ev.to);
    wrapper.classList.remove('is-sliding');
  });
  carousel.addEventListener('click', ev => {
    const peek = ev.target.closest('.carousel-item.peek-left, .carousel-item.peek-right');
    if (!peek) return;
    console.log('peek click', peek.classList.contains('peek-left') ? 'left' : 'right');
    peek.classList.contains('peek-left') ? bsCarousel.prev() : bsCarousel.next();
  });
})();
